/**
 * OpenAPI 3.1 document for the Stridash REST API.
 *
 * Kept as a typed object (not generated by decorators) because the routes use
 * plain Hono + zod request parsing. `npm run openapi:generate -w @stridash/server`
 * writes docs/openapi.json from this source; the server also serves it at
 * /api/openapi.json so clients/MCP can discover the API at runtime.
 */

const errorResponse = {
  description: 'Request failed',
  content: {
    'application/json': { schema: { $ref: '#/components/schemas/Error' } },
  },
} as const;

const jsonResponse = (schema: unknown, description = 'OK') => ({
  description,
  content: { 'application/json': { schema } },
});

const object = { type: 'object', additionalProperties: true } as const;
const arrayOf = (items: unknown) => ({ type: 'array', items });

const bearer = [{ bearerAuth: [] }] as const;

const authBody = {
  type: 'object',
  required: ['email', 'password'],
  properties: {
    email: { type: 'string', format: 'email', maxLength: 254 },
    password: { type: 'string', minLength: 8, maxLength: 1024 },
  },
} as const;

const refreshBody = {
  type: 'object',
  required: ['refreshToken'],
  properties: { refreshToken: { type: 'string' } },
} as const;

const idParam = {
  name: 'id',
  in: 'path',
  required: true,
  schema: { type: 'string', format: 'uuid' },
} as const;

const listParams = [
  { name: 'limit', in: 'query', schema: { type: 'integer', minimum: 1, maximum: 100 } },
  { name: 'cursor', in: 'query', schema: { type: 'string', format: 'uuid' } },
  { name: 'from', in: 'query', schema: { type: 'string', format: 'date-time' } },
  { name: 'to', in: 'query', schema: { type: 'string', format: 'date-time' } },
] as const;

const listResponse = jsonResponse({
  type: 'object',
  properties: {
    items: arrayOf(object),
    nextCursor: { type: ['string', 'null'], format: 'uuid' },
  },
});

const connectBody = {
  oneOf: [
    {
      type: 'object',
      required: ['provider', 'identifier', 'password', 'country'],
      properties: {
        provider: { const: 'OMRON' },
        identifier: { type: 'string' },
        password: { type: 'string' },
        country: { type: 'string', minLength: 2, maxLength: 2 },
      },
    },
    {
      type: 'object',
      required: ['provider', 'username', 'password'],
      properties: {
        provider: { enum: ['IGPSPORT', 'ZWIFT'] },
        username: { type: 'string' },
        password: { type: 'string' },
        region: { enum: ['intl', 'cn'] },
      },
    },
    {
      type: 'object',
      required: ['provider', 'email', 'password'],
      properties: {
        provider: { const: 'GARMIN' },
        email: { type: 'string', format: 'email' },
        password: { type: 'string' },
      },
    },
  ],
} as const;

const measurementBody = {
  oneOf: [
    {
      type: 'object',
      required: ['kind', 'weightKg'],
      properties: {
        kind: { const: 'WEIGH_IN' },
        measuredAt: { type: 'string', format: 'date-time' },
        weightKg: { type: 'number', minimum: 0, maximum: 500 },
        bodyFatPct: { type: 'number', minimum: 0, maximum: 80 },
        muscleMassKg: { type: 'number' },
        skeletalMusclePct: { type: 'number' },
        bmi: { type: 'number' },
        visceralFatLevel: { type: 'number' },
        notes: { type: 'string', maxLength: 1000 },
      },
    },
    {
      type: 'object',
      required: ['kind', 'systolicMmhg', 'diastolicMmhg'],
      properties: {
        kind: { const: 'BLOOD_PRESSURE' },
        measuredAt: { type: 'string', format: 'date-time' },
        systolicMmhg: { type: 'integer', minimum: 70, maximum: 260 },
        diastolicMmhg: { type: 'integer', minimum: 40, maximum: 150 },
        pulseBpm: { type: 'integer', minimum: 20, maximum: 250 },
        notes: { type: 'string', maxLength: 1000 },
      },
    },
  ],
} as const;

const gearComponentBody = {
  type: 'object',
  required: ['name', 'kind'],
  properties: {
    name: { type: 'string' },
    kind: {
      enum: [
        'CHAIN',
        'CASSETTE',
        'CHAINRING',
        'BRAKE_PADS',
        'TIRES',
        'TUBES',
        'PEDALS',
        'BATTERY',
        'OTHER',
      ],
    },
    installedAt: { type: 'string', format: 'date' },
    thresholdM: { type: 'number' },
    notes: { type: 'string' },
  },
} as const;

export function openapiDocument(version = '0.1.0') {
  return {
    openapi: '3.1.0',
    info: {
      title: 'Stridash API',
      version,
      description:
        'Self-hosted fitness aggregator. App JWTs authenticate all routes except health, auth, and the Strava callback.',
    },
    servers: [{ url: '/' }],
    tags: [
      { name: 'health' },
      { name: 'auth' },
      { name: 'strava' },
      { name: 'connections' },
      { name: 'activities' },
      { name: 'measurements' },
      { name: 'wellness' },
      { name: 'gear' },
      { name: 'account' },
    ],
    components: {
      securitySchemes: {
        bearerAuth: { type: 'http', scheme: 'bearer', bearerFormat: 'JWT' },
      },
      schemas: {
        Error: {
          type: 'object',
          required: ['error'],
          properties: {
            error: { type: 'string' },
            detail: {},
          },
        },
        AuthTokens: {
          type: 'object',
          required: ['accessToken', 'refreshToken'],
          properties: {
            accessToken: { type: 'string' },
            refreshToken: { type: 'string' },
          },
        },
        Health: {
          type: 'object',
          properties: {
            status: { const: 'ok' },
            version: { type: 'string' },
            startedAt: { type: 'string', format: 'date-time' },
          },
        },
        Connection: object,
        Activity: object,
        Measurement: object,
        SyncLog: object,
        Gear: object,
      },
    },
    paths: {
      '/api/health': {
        get: {
          tags: ['health'],
          summary: 'Health + version',
          responses: { '200': jsonResponse({ $ref: '#/components/schemas/Health' }) },
        },
      },
      '/api/openapi.json': {
        get: {
          tags: ['health'],
          summary: 'This OpenAPI document',
          responses: { '200': jsonResponse(object) },
        },
      },

      '/api/auth/register': {
        post: {
          tags: ['auth'],
          summary: 'Create an account and return a token pair',
          requestBody: {
            required: true,
            content: {
              'application/json': {
                schema: {
                  ...authBody,
                  required: ['email', 'password', 'displayName'],
                  properties: {
                    ...authBody.properties,
                    displayName: { type: 'string', minLength: 1, maxLength: 80 },
                  },
                },
              },
            },
          },
          responses: {
            '201': jsonResponse({
              allOf: [{ $ref: '#/components/schemas/AuthTokens' }, object],
            }),
            '400': errorResponse,
            '409': errorResponse,
          },
        },
      },
      '/api/auth/login': {
        post: {
          tags: ['auth'],
          summary: 'Log in',
          requestBody: {
            required: true,
            content: { 'application/json': { schema: authBody } },
          },
          responses: {
            '200': jsonResponse({
              allOf: [{ $ref: '#/components/schemas/AuthTokens' }, object],
            }),
            '401': errorResponse,
          },
        },
      },
      '/api/auth/refresh': {
        post: {
          tags: ['auth'],
          summary: 'Rotate a refresh token',
          requestBody: {
            required: true,
            content: { 'application/json': { schema: refreshBody } },
          },
          responses: {
            '200': jsonResponse({ $ref: '#/components/schemas/AuthTokens' }),
            '401': errorResponse,
          },
        },
      },
      '/api/auth/logout': {
        post: {
          tags: ['auth'],
          summary: 'Revoke a refresh-token family',
          requestBody: {
            required: true,
            content: { 'application/json': { schema: refreshBody } },
          },
          responses: { '204': { description: 'Logged out' } },
        },
      },

      '/api/strava/authorize': {
        get: {
          tags: ['strava'],
          summary: 'Strava consent URL',
          security: bearer,
          responses: {
            '200': jsonResponse({
              type: 'object',
              properties: { url: { type: 'string', format: 'uri' } },
            }),
            '401': errorResponse,
            '503': errorResponse,
          },
        },
      },
      '/api/strava/callback': {
        get: {
          tags: ['strava'],
          summary: 'Strava OAuth callback (browser redirect)',
          parameters: [
            { name: 'code', in: 'query', schema: { type: 'string' } },
            { name: 'state', in: 'query', schema: { type: 'string' } },
            { name: 'error', in: 'query', schema: { type: 'string' } },
          ],
          responses: { '302': { description: 'Redirect back to /connections' } },
        },
      },

      '/api/connections': {
        get: {
          tags: ['connections'],
          summary: 'List provider connections (tokens excluded)',
          security: bearer,
          responses: { '200': listResponse },
        },
        post: {
          tags: ['connections'],
          summary: 'Connect a provider with credentials',
          security: bearer,
          requestBody: {
            required: true,
            content: { 'application/json': { schema: connectBody } },
          },
          responses: {
            '201': jsonResponse({ $ref: '#/components/schemas/Connection' }),
            '202': jsonResponse({
              type: 'object',
              properties: {
                mfaRequired: { type: 'boolean' },
                method: { type: 'string' },
                connection: { $ref: '#/components/schemas/Connection' },
              },
            }),
            '400': errorResponse,
            '401': errorResponse,
            '429': errorResponse,
          },
        },
      },
      '/api/connections/{id}/mfa': {
        post: {
          tags: ['connections'],
          summary: 'Complete a pending Garmin MFA login',
          security: bearer,
          parameters: [idParam],
          requestBody: {
            required: true,
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  required: ['code'],
                  properties: { code: { type: 'string' } },
                },
              },
            },
          },
          responses: {
            '200': jsonResponse({ $ref: '#/components/schemas/Connection' }),
            '400': errorResponse,
            '401': errorResponse,
            '404': errorResponse,
            '409': errorResponse,
          },
        },
      },
      '/api/connections/{id}': {
        delete: {
          tags: ['connections'],
          summary: 'Soft-revoke a connection and wipe its tokens',
          security: bearer,
          parameters: [idParam],
          responses: { '200': jsonResponse(object), '404': errorResponse },
        },
      },
      '/api/connections/{id}/sync': {
        post: {
          tags: ['connections'],
          summary: 'Queue a manual sync',
          security: bearer,
          parameters: [idParam],
          responses: {
            '202': jsonResponse({
              type: 'object',
              properties: {
                status: { const: 'queued' },
                inProgress: { type: 'boolean' },
                syncStartedAt: { type: 'string', format: 'date-time' },
              },
            }),
            '404': errorResponse,
            '409': errorResponse,
            '501': errorResponse,
          },
        },
      },
      '/api/connections/{id}/syncs': {
        get: {
          tags: ['connections'],
          summary: 'Recent sync logs + in-progress state',
          security: bearer,
          parameters: [idParam],
          responses: { '200': jsonResponse(object), '404': errorResponse },
        },
      },

      '/api/activities': {
        get: {
          tags: ['activities'],
          summary: 'Activity feed',
          security: bearer,
          parameters: listParams,
          responses: { '200': listResponse },
        },
      },
      '/api/activities/{id}': {
        get: {
          tags: ['activities'],
          summary: 'Activity detail + series',
          security: bearer,
          parameters: [idParam],
          responses: { '200': jsonResponse(object), '404': errorResponse },
        },
      },
      '/api/activities/{id}/similar': {
        get: {
          tags: ['activities'],
          summary: 'Similar activities for comparison',
          security: bearer,
          parameters: [idParam],
          responses: { '200': listResponse, '404': errorResponse },
        },
      },
      '/api/activities/{id}/resync': {
        post: {
          tags: ['activities'],
          summary: 'Force re-sync from the owning provider',
          security: bearer,
          parameters: [idParam],
          responses: {
            '200': jsonResponse(object),
            '404': errorResponse,
            '409': errorResponse,
            '501': errorResponse,
          },
        },
      },

      '/api/measurements': {
        get: {
          tags: ['measurements'],
          summary: 'Weigh-ins and blood-pressure readings',
          security: bearer,
          parameters: listParams,
          responses: { '200': listResponse },
        },
        post: {
          tags: ['measurements'],
          summary: 'Manual weigh-in or blood-pressure quick-add',
          security: bearer,
          requestBody: {
            required: true,
            content: { 'application/json': { schema: measurementBody } },
          },
          responses: {
            '201': jsonResponse({ $ref: '#/components/schemas/Measurement' }),
            '400': errorResponse,
            '409': errorResponse,
          },
        },
      },

      '/api/sleeps': {
        get: {
          tags: ['wellness'],
          summary: 'Sleep sessions',
          security: bearer,
          parameters: listParams,
          responses: { '200': listResponse },
        },
      },
      '/api/wellness': {
        get: {
          tags: ['wellness'],
          summary: 'Daily wellness rows',
          security: bearer,
          parameters: listParams,
          responses: { '200': listResponse },
        },
      },

      '/api/gear': {
        get: {
          tags: ['gear'],
          summary: 'Gear + computed usage',
          security: bearer,
          responses: { '200': listResponse },
        },
      },
      '/api/gear/{gearId}/components': {
        post: {
          tags: ['gear'],
          summary: 'Add a wear component to a gear item',
          security: bearer,
          parameters: [{ ...idParam, name: 'gearId' }],
          requestBody: {
            required: true,
            content: { 'application/json': { schema: gearComponentBody } },
          },
          responses: {
            '201': jsonResponse(object),
            '400': errorResponse,
            '404': errorResponse,
          },
        },
      },
      '/api/gear/components/{componentId}': {
        patch: {
          tags: ['gear'],
          summary: 'Retire/update a gear component',
          security: bearer,
          parameters: [{ ...idParam, name: 'componentId' }],
          requestBody: {
            required: true,
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  properties: {
                    name: { type: 'string' },
                    installedAt: { type: ['string', 'null'], format: 'date' },
                    retiredAt: { type: ['string', 'null'], format: 'date' },
                    thresholdM: { type: ['number', 'null'] },
                    notes: { type: ['string', 'null'] },
                  },
                },
              },
            },
          },
          responses: { '200': jsonResponse(object), '404': errorResponse },
        },
        delete: {
          tags: ['gear'],
          summary: 'Delete a gear component',
          security: bearer,
          parameters: [{ ...idParam, name: 'componentId' }],
          responses: { '200': jsonResponse(object), '404': errorResponse },
        },
      },

      '/api/me': {
        get: {
          tags: ['account'],
          summary: 'Account + preferences + chart configuration',
          security: bearer,
          responses: { '200': jsonResponse(object), '404': errorResponse },
        },
        patch: {
          tags: ['account'],
          summary: 'Update account/preferences',
          security: bearer,
          requestBody: {
            required: true,
            content: { 'application/json': { schema: object } },
          },
          responses: { '200': jsonResponse(object), '400': errorResponse },
        },
        delete: {
          tags: ['account'],
          summary: 'Delete the account and all user data',
          security: bearer,
          responses: { '200': jsonResponse(object), '404': errorResponse },
        },
      },
      '/api/preferences/charts/{provider}': {
        put: {
          tags: ['account'],
          summary: 'Replace one provider’s chart channel order/visibility',
          security: bearer,
          parameters: [
            { name: 'provider', in: 'path', required: true, schema: { type: 'string' } },
          ],
          requestBody: {
            required: true,
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  required: ['channels'],
                  properties: {
                    channels: arrayOf({
                      type: 'object',
                      required: ['key', 'visible'],
                      properties: {
                        key: { type: 'string' },
                        visible: { type: 'boolean' },
                      },
                    }),
                  },
                },
              },
            },
          },
          responses: { '200': jsonResponse(object), '400': errorResponse },
        },
      },
      '/api/export': {
        get: {
          tags: ['account'],
          summary: 'Full JSON account export (streamed)',
          security: bearer,
          responses: {
            '200': {
              description: 'JSON attachment',
              content: { 'application/json': { schema: object } },
            },
          },
        },
      },
      '/api/export/csv': {
        get: {
          tags: ['account'],
          summary: 'CSV export (streamed)',
          security: bearer,
          parameters: [
            {
              name: 'type',
              in: 'query',
              required: true,
              schema: { enum: ['activities', 'measurements', 'sleep', 'wellness'] },
            },
          ],
          responses: {
            '200': {
              description: 'CSV attachment',
              content: { 'text/csv': { schema: { type: 'string' } } },
            },
            '400': errorResponse,
          },
        },
      },
    },
  } as const;
}
